export const meta = {
  name: 'adr-claim-verification',
  description: 'Two independent refute-by-default verifiers per ADR: code/spec truth and source truth',
  phases: [ { title: 'Verify', detail: '2 lenses x 8 ADRs, read-only' } ],
}
const WT = args.wt
const ADRS = args.adrs
const LENSES = {
  code: `LENS: code and spec truth. For EVERY factual statement about current callisto behavior, types, functions, files, config keys, commands, tests, CI checks, enforcement, or consequences: find it in the current code (${WT}) and confirm or refute it. Also check the ADR agrees with docs/specs/*.json, docs/adr/README.md's index line for it, the owner decisions in docs/projects/ROAD-TO-V1.md ("v1 fix plan" section), and the other ADRs. Also judge: is this a real callisto product decision (not this repo's own setup), and is the title/decision an accurate description of what the system does?`,
  source: `LENS: source truth. For EVERY quote, citation, commit sha, PR number, section reference and stated reason: open the source (git show <sha>, git log, gh pr view <n> --repo orin-dx/callisto --json title,body, git show <sha>^:<deleted path>) and confirm it says exactly that. Flag any reason that is inferred or paraphrased beyond what the source says, any number that does not match, and any citation that points to the wrong thing. Deleted docs are only in history: find them with git log --all --diff-filter=D -- <path>.`,
}
const V = { type: 'object', properties: {
  claims: { type: 'array', items: { type: 'object', properties: {
    quote: { type: 'string' }, verdict: { type: 'string', enum: ['confirmed', 'wrong', 'unsupported', 'misleading'] },
    evidence: { type: 'string', description: 'file:line or sha/PR and what it actually says' },
    fix: { type: 'string', description: 'replacement text, or delete; empty when confirmed' } },
    required: ['quote', 'verdict', 'evidence'] } },
  overall: { type: 'string', description: 'one line: is this ADR accurate and a real product decision' } },
  required: ['claims', 'overall'] }
const jobs = []
